        "A": "It intervenes in prices on the national markets, and can fine companies which do not comply",
        "B": "It can halt mergers in any circumstance, without the review of the European Courts because it is a Commission full competence",
        "C": "It monitors and investigates anti-competition practices, mergers and state aid",
