      "rationale": "The European Commission, together with the national competition authorities, directly enforces EU competition rules, to make EU markets work better, by ensuring that all companies compete equally and fairly on their merits. Within the Commission, the Directorate-General (DG) for Competition is primarily responsible for these direct enforcement powers. Reference: https://commission.europa.eu/about-european-commission/departments-and-executive-agencies/competition_en",
