      "answer": "C",
      "rationale": "A. False. Inflation increased in twelve Member States.\nB. Cannot say. The passage discusses two different sets of inflation rates, one for the whole of the EU and the other just for the euro area. The statement is true in respect of the annual euro area inflation rate, but we are not told whether this was also true of the inflation rate for the EU as a whole.\nC. True. Portugal had a negative annual inflation rate of -0.1% during the period observed.\nD. False. Inflation within the euro area was 1.0% exactly, and not over it.",
