      "id": "verbal-q-93",
      "part": "Verbal Reasoning",
      "number": 93,
      "prompt": "The US has fallen behind several countries around the world in terms of educational mobility and university-level educational attainment. The number of young people attending and graduating from university has in the past surpassed the numbers of the previous generation. Today, however, that is not always true, and fewer young adults are getting a higher education than their parents. Several factors contribute to this trend. One of the biggest reasons that fewer individuals are going to university is the cost. Tuition costs at public universities have drastically increased over the last few decades, leading to less equitable access to education. This indicates that those from lower socioeconomic classes have a more difficult time paying for and attending university. (worldatlas.com)",
